"""HTML -> translatable text blocks, with CAT-style word counting."""
import re, html, unicodedata
from html.parser import HTMLParser

SKIP_TAGS = {"script", "style", "noscript", "template", "svg", "canvas",
             "iframe", "object", "embed", "audio", "video", "map", "area",
             "code", "pre"}          # code/pre tracked separately below
HARD_SKIP = {"script", "style", "noscript", "template", "svg", "canvas",
             "iframe", "object", "embed"}
VOID = {"br", "hr", "img", "input", "meta", "link", "source", "track", "wbr",
        "col", "base", "area", "param", "embed"}
BLOCK = {"p", "div", "h1", "h2", "h3", "h4", "h5", "h6", "li", "td", "th",
         "tr", "section", "article", "header", "footer", "nav", "aside",
         "main", "ul", "ol", "dl", "dt", "dd", "blockquote", "pre", "figure",
         "figcaption", "table", "thead", "tbody", "tfoot", "form", "label",
         "fieldset", "legend", "button", "br", "hr", "address", "details",
         "summary", "option", "caption", "hgroup", "dialog"}

HIDDEN_CLASS = re.compile(r"\b(w-condition-invisible|w-dyn-bind-empty|"
                          r"hidden|sr-only|visually-hidden|screen-reader)\b")
DISPLAY_NONE = re.compile(r"display\s*:\s*none", re.I)

ATTR_FIELDS = {"alt": "img_alt", "placeholder": "placeholder",
               "aria-label": "aria_label", "title": "title_attr",
               "value": "input_value"}


class Doc(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.skip = 0          # inside script/style/etc
        self.hidden = 0        # inside display:none / .hidden
        self.in_head = False
        self.in_title = False
        self.lang = ""
        self.title = ""
        self.meta = {}         # name/property -> content
        self.blocks = []       # (text, hidden_bool)
        self.attr_items = []   # (kind, text)
        self._buf = []
        self._hidden_now = False
        self._stack = []

    # ---- helpers
    def _flush(self):
        t = " ".join("".join(self._buf).split())
        if t:
            self.blocks.append((t, self._hidden_now))
        self._buf = []
        self._hidden_now = self.hidden > 0

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        a = {k.lower(): (v or "") for k, v in attrs}
        if tag == "html":
            self.lang = a.get("lang", "")
        if tag == "head":
            self.in_head = True
        if tag == "title" and self.in_head:
            self.in_title = True
        if tag == "meta":
            key = a.get("name") or a.get("property") or ""
            if key.lower() in ("description", "og:title", "og:description",
                               "twitter:title", "twitter:description"):
                self.meta[key.lower()] = a.get("content", "")
        if tag in HARD_SKIP:
            self.skip += 1
            if tag not in VOID:
                self._stack.append((tag, "skip"))
            return
        if self.skip:
            if tag not in VOID:
                self._stack.append((tag, None))
            return

        is_hidden = bool(DISPLAY_NONE.search(a.get("style", "")) or
                         HIDDEN_CLASS.search(a.get("class", "")) or
                         "hidden" in a)
        if tag in BLOCK:
            self._flush()
        if is_hidden:
            self.hidden += 1
            self._hidden_now = True
        # translatable attributes
        for att, kind in ATTR_FIELDS.items():
            if att in a:
                if att == "value" and a.get("type", "").lower() not in (
                        "submit", "button", "reset"):
                    continue
                v = " ".join(a[att].split())
                if v and not v.startswith(("http", "{{", "/")):
                    self.attr_items.append((kind, v))
        if tag not in VOID:
            self._stack.append((tag, "hid" if is_hidden else None))

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag == "head":
            self.in_head = False
        if tag == "title":
            self.in_title = False
        # unwind to matching tag
        for i in range(len(self._stack) - 1, -1, -1):
            if self._stack[i][0] == tag:
                for t, mark in self._stack[i:]:
                    if mark == "skip":
                        self.skip = max(0, self.skip - 1)
                    elif mark == "hid":
                        self.hidden = max(0, self.hidden - 1)
                del self._stack[i:]
                break
        if tag in BLOCK and not self.skip:
            self._flush()
        self._hidden_now = self.hidden > 0

    def handle_data(self, d):
        if self.in_title:
            self.title += d
            return
        if self.skip or self.in_head:
            return
        if d.strip():
            self._buf.append(d)

    def close(self):
        super().close()
        self._flush()


# ---------- counting ----------
CJK = re.compile(r"[㐀-䶿一-鿿豈-﫿぀-ゟ"
                 r"゠-ヿ가-힯々〆ー]")
WORDish = re.compile(r"[^\W_]", re.U)
# strip pure punctuation / symbol tokens
NUMONLY = re.compile(r"^[\d\s.,:;%+\-/()\[\]]+$")


def count_text(t, cjk_mode=False):
    """Return (words, chars_nospace, cjk_chars)."""
    t = unicodedata.normalize("NFC", t)
    cjk_chars = len(CJK.findall(t))
    chars_ns = len(re.sub(r"\s", "", t))
    # non-CJK portion: whitespace tokens containing a word character
    stripped = CJK.sub(" ", t)
    toks = [w for w in stripped.split() if WORDish.search(w)]
    latin_words = len(toks)
    if cjk_mode:
        # CAT convention: each CJK char counts as one unit
        words = latin_words + cjk_chars
    else:
        words = latin_words + cjk_chars
    return words, chars_ns, cjk_chars, latin_words


SENT_SPLIT = re.compile(r"(?<=[.!?。！？؟…])[\s ]+(?=[^\s])")


def segments(block):
    """Split a text block into CAT-style segments (sentences)."""
    block = block.strip()
    if not block:
        return []
    parts = [p.strip() for p in SENT_SPLIT.split(block) if p.strip()]
    return parts or [block]


def norm_seg(s):
    """Normalise a segment for exact-repetition matching."""
    s = unicodedata.normalize("NFKC", s).lower()
    s = re.sub(r"\s+", " ", s)
    s = re.sub(r"[‘’“”–—]", "'", s)
    s = s.strip(" \t.,;:!?·|-–—\"'()[]")
    return s


def parse(raw_bytes):
    txt = raw_bytes.decode("utf-8", "replace")
    d = Doc()
    try:
        d.feed(txt)
        d.close()
    except Exception:
        pass
    return d

