#!/usr/bin/env python3
import csv, collections, os
from urllib.parse import urlsplit

HERE = os.path.dirname(os.path.abspath(__file__))
rows = list(csv.DictReader(open(os.path.join(HERE, "out", "all_pages.csv"))))
LOC = ["pt", "es", "fr", "de", "ko", "it", "ar", "zh", "ja", "sv"]

loc_slugs = collections.defaultdict(set)
en = {}
for r in rows:
    path = urlsplit(r["url"]).path.strip("/")
    loc = r["locale"]
    if loc == "en":
        en[path] = int(r["words"])
    else:
        rest = path[len(loc):].strip("/")
        if "/" in rest:
            loc_slugs[loc].add(rest.split("/", 1)[1])
        else:
            loc_slugs[loc].add(rest)

enblog = {k: v for k, v in en.items() if k.startswith("blog/")}
print(f"EN pages total: {len(en)}   EN blog posts: {len(enblog)}")
print(f"EN non-blog pages: {len(en) - len(enblog)}")
print()
print("EN blog-post slugs present in each locale:")
for l in LOC:
    s = loc_slugs[l]
    hit = sum(1 for k in enblog if k.split("/", 1)[1] in s)
    missing_w = sum(v for k, v in enblog.items()
                    if k.split("/", 1)[1] not in s)
    print(f"  {l}: {hit:>4}/{len(enblog)} translated | "
          f"missing {len(enblog)-hit:>4} posts = {missing_w:>9,} words")
